-- Preserve existing snapshots and their FK lineage; broaden retention only with
-- explicit private-processing permission recorded alongside each immutable input.
SET LOCAL ROLE tv_source_ingestion_owner;
ALTER TABLE source_ingestion.synthetic_inputs RENAME TO retained_inputs;
-- The three legacy CHECK names were generated by PostgreSQL. Replace only
-- checks on this table; retain its primary key and delivery foreign key.
DO $migration$
DECLARE legacy_check record;
BEGIN
  FOR legacy_check IN SELECT conname FROM pg_constraint
    WHERE conrelid='source_ingestion.retained_inputs'::regclass AND contype='c'
  LOOP
    EXECUTE format('ALTER TABLE source_ingestion.retained_inputs DROP CONSTRAINT %I', legacy_check.conname);
  END LOOP;
END;
$migration$;
ALTER TABLE source_ingestion.retained_inputs
  ADD CONSTRAINT retained_canonical_object CHECK (jsonb_typeof(canonical) = 'object'),
  ADD COLUMN permission jsonb;
UPDATE source_ingestion.retained_inputs SET permission = jsonb_build_object(
  'sourceId', canonical #>> '{observation,sourceId}',
  'provider', canonical #>> '{observation,sourceDeliveryId,provider}',
  'accountScope', canonical #>> '{observation,sourceDeliveryId,accountScope}',
  'sourceEpoch', canonical #>> '{observation,sourceDeliveryId,sourceEpoch}',
  'purpose', 'PRIVATE_PROCESSING', 'retentionAllowed', true,
  'evidenceReference', 'repository-synthetic-fixtures-only');
ALTER TABLE source_ingestion.retained_inputs ALTER COLUMN permission SET NOT NULL;
ALTER TABLE source_ingestion.retained_inputs ADD CONSTRAINT retained_permission_scope CHECK ((
  jsonb_typeof(permission) = 'object'
  AND permission->'retentionAllowed' = 'true'::jsonb
  AND permission->>'purpose' = 'PRIVATE_PROCESSING'
  AND jsonb_typeof(permission->'evidenceReference') = 'string'
  AND length(btrim(permission->>'evidenceReference')) BETWEEN 1 AND 512
  AND permission->>'sourceId' = canonical #>> '{observation,sourceId}'
  AND permission->>'provider' = canonical #>> '{observation,sourceDeliveryId,provider}'
  AND permission->>'accountScope' = canonical #>> '{observation,sourceDeliveryId,accountScope}'
  AND permission->>'sourceEpoch' = canonical #>> '{observation,sourceDeliveryId,sourceEpoch}'
) IS TRUE);
RESET ROLE;
